// STUB — Phase 8 Skeleton
// PURPOSE: Read approval_status from incoming item and validate it
// PRODUCTION: Read from Google Sheets approval queue row or Supabase record
// CREDENTIAL NEEDED: REPLACE_WITH_GOOGLE_SHEETS_CREDENTIAL or REPLACE_WITH_SUPABASE_CREDENTIAL
// APPROVAL RULE: Only 'Approved' status allows proceed to publish path
// OWNER RULE: Only Owner (Bo Bao) can set approval_status='Approved'

const inputData = $input.first().json;

// Read fields from incoming approval request
const approval_status = inputData.approval_status || 'Draft';
const item_type = inputData.item_type || 'UNKNOWN';
const item_id = inputData.item_id || 'UNKNOWN';
const owner_decision = inputData.owner_decision || null;

// Hard block check — missing approval
const approvalValid = (
  approval_status === 'Approved' &&
  owner_decision === 'Approved'
);

const approvalBlockReason = !approvalValid
  ? `MISSING_APPROVAL — approval_status=${approval_status}, owner_decision=${owner_decision}. Owner must set both to Approved.`
  : null;

return [{
  json: {
    ...inputData,
    approval_status,
    item_type,
    item_id,
    owner_decision,
    approval_valid: approvalValid,
    approval_block_reason: approvalBlockReason,
    approvalCheckCompleted: true
  }
}];

// STUB — Phase 8 Skeleton
// PURPOSE: Write log entry for blocked (not-approved) items
// PRODUCTION: Append to Google Sheets log tab or Supabase logs table

const inputData = $input.first().json;

const logEntry = {
  log_id: 'LOG-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-BLOCK-001',
  timestamp: new Date().toISOString(),
  phase: '8',
  agent_name: 'n8n-approval-publishing-gate (STUB)',
  action_type: 'Approval Decision',
  input_ref: inputData.item_id || 'STUB_INPUT',
  output_ref: 'BLOCKED_NOT_APPROVED',
  status: 'Blocked',
  summary: `Item ${inputData.item_id} blocked: approval_status=${inputData.approval_status}. No publishing action taken.`,
  errors: [inputData.approval_block_reason || 'MISSING_APPROVAL'],
  next_action: 'Owner to set approval_status=Approved before item can proceed.',
  owner_action_required: true
};

return [{ json: { ...inputData, logEntry, logWritten: true, publishingBlocked: true } }];

// STUB — Phase 8 Skeleton
// PURPOSE: Write structured approval log entry per schemas/log-entry.schema.json
// PRODUCTION: Append to Google Sheets log tab or Supabase logs table
// CREDENTIAL NEEDED: REPLACE_WITH_GOOGLE_SHEETS_CREDENTIAL or REPLACE_WITH_SUPABASE_CREDENTIAL

const inputData = $input.first().json;

const logEntry = {
  log_id: 'LOG-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-APPR-001',
  timestamp: new Date().toISOString(),
  phase: '8',
  agent_name: 'n8n-approval-publishing-gate (STUB)',
  action_type: 'Approval Decision',
  input_ref: inputData.item_id || 'STUB_INPUT',
  output_ref: `APPROVED_${inputData.item_type || 'UNKNOWN'}_STUB`,
  status: 'Success',
  summary: `Item ${inputData.item_id} passed approval gate with status=${inputData.approval_status}. Publish stub executed (no real publish in skeleton).`,
  errors: null,
  next_action: 'Item routed to publish stub. In production, replace NoOp stubs with real platform publish nodes.',
  owner_action_required: false
};

return [{ json: { ...inputData, logEntry, logWritten: true, approvalLogged: true } }];
